@page "/dispatcher"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject ShipmentService ShipmentService

<PageTitle>Dispatcher</PageTitle>

<h1>Dispatcher - All Shipments</h1>

<div class="mb-3">
    <input type="text" class="form-control" placeholder="Search by tracking number or destination..."
           @bind="searchFilter" @bind:event="oninput" />
</div>

@if (shipments is not null)
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Action</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.EstimatedDelivery.ToShortDateString()</td>
                    <td>
                        <select class="form-select form-select-sm" value="@shipment.Status"
                                @onchange="(e) => UpdateStatus(shipment, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}
else
{
    <p><em>Loading shipments...</em></p>
}

@code {
    private List<Shipment>? shipments;
    private string searchFilter = string.Empty;

    private IEnumerable<Shipment> FilteredShipments =>
        shipments?.Where(s =>
            string.IsNullOrEmpty(searchFilter) ||
            s.TrackingNumber.Contains(searchFilter, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(searchFilter, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            shipment.Status = newStatus;
            await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
        }
    }

    private string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.InTransit => "bg-info",
        ShipmentStatus.OutForDelivery => "bg-primary",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject ShipmentService ShipmentService

<PageTitle>Track My Shipments</PageTitle>

<h1>My Shipments</h1>

<div class="mb-3">
    <input type="text" class="form-control" placeholder="Filter by tracking number..."
           @bind="searchFilter" @bind:event="oninput" />
</div>

@if (shipments is not null)
{
    @if (!FilteredShipments.Any())
    {
        <div class="alert alert-info">No shipments found for your account.</div>
    }
    else
    {
        <div class="row">
            @foreach (var shipment in FilteredShipments)
            {
                <div class="col-md-6 mb-3">
                    <div class="card">
                        <div class="card-body">
                            <h5 class="card-title">@shipment.TrackingNumber</h5>
